export default function (apiIdentifier, info) {
    return async function (assetId) {
        try {
            const result = await info.fns.resolveUri(`matrix-asset://${apiIdentifier}/${assetId}`);
            if ('ok' in result && ('data' in result || 'reason' in result))
                return result;
            if (result !== undefined) {
                return {
                    ok: true,
                    data: result
                };
            }
            throw new Error('Unknown response', { cause: result });
        }
        catch (error) {
            const err = (error || { message: 'Unknown Error' });
            return {
                ok: false,
                data: null,
                error: err,
                reason: err.cause || 'Unknown reason'
            };
        }
    };
}
